package com.argument.automation;
import com.argument.common.exception.*;
import com.argument.integration.*;
import com.argument.version.*;
import com.argument.version.local.*;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.node.*;
import org.junit.jupiter.api.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.boot.test.mock.mockito.SpyBean;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.test.context.ActiveProfiles;
import org.springframework.test.web.servlet.MockMvc;
import java.util.*;
import java.util.concurrent.*;
import static org.assertj.core.api.Assertions.*;
import static org.mockito.Mockito.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;

@SpringBootTest @AutoConfigureMockMvc @ActiveProfiles("test")
class AutomationWorkflowTest {
 @Autowired AutomationTaskService service;@Autowired AutomationWorker worker;@Autowired LocalFixtureLoader loader;@Autowired LocalAccountLoader accounts;@Autowired LocalAnnotationDependencies data;@Autowired UnifiedVersionIdentity identity;@Autowired VersionRepository versions;@Autowired ObjectMapper mapper;@Autowired JdbcTemplate jdbc;@Autowired MockMvc mvc;
 @SpyBean AutomationRepository repository;@SpyBean TestAutomationModelAdapter adapter;
 String token,caseId,taskId;com.argument.version.port.VersionIdentity.Actor creator;
 void clean(){for(String t:List.of("workflow_command_history","trial_correction_rounds","trial_segmentation_records","trial_downloads","trial_files","trial_data_events","trial_exports","trial_export_receipts","trial_final_commitments","trial_audit_events","final_review_transitions","final_annotation_versions","adjudication_transitions","adjudication_returned_versions","adjudication_decisions","adjudication_items","adjudication_sessions","annotation_mutation_receipts","snapshot_object_owners","annotation_version_snapshots","annotation_versions","annotation_case_counters","workflow_records"))jdbc.update("DELETE FROM "+t);}
 @BeforeEach void setup()throws Exception{reset(repository,adapter);clean();loader.run(null);accounts.run(null);token=call("/api/v1/auth/login",null,mapper.createObjectNode().put("username","creator.li").put("password","demo"),null,null,200).path("data").path("token").asText();creator=identity.authenticate("Bearer "+token);var original=data.read("taskDocument","3cbb140f-0274-4871-8248-194271101a14");var create=mapper.createObjectNode().put("name","自动任务实际来源验收").put("guideVersionId",data.read("task",original.path("taskId").asText()).path("guideVersionId").asText()).put("taskType","FORMAL_RESEARCH").put("defaultRequiredAnnotators",2).put("autoPreannotationEnabled",true).put("expertConfirmationRequired",false).put("adjudicationReasonRequired",true);taskId=call("/api/v1/tasks",token,create,VersionJson.uuid(),null,200).path("data").path("id").asText();var body=mapper.createObjectNode().put("requiredAnnotators",2);for(String f:List.of("documentId","documentTextVersionId","annotationScopeId"))body.set(f,original.get(f));caseId=call("/api/v1/tasks/"+taskId+"/documents",token,body,VersionJson.uuid(),null,200).path("data").path("id").asText();}
 @AfterEach void after(){reset(repository,adapter);clean();}
 ObjectNode call(String path,String auth,ObjectNode body,String key,Integer version,int expected)throws Exception{var request=post(path).contentType("application/json").content(body.toString());if(auth!=null)request.header("Authorization","Bearer "+auth);if(key!=null)request.header("Idempotency-Key",key);if(version!=null)request.header("If-Match",version);var r=mvc.perform(request).andReturn().getResponse();assertThat(r.getStatus()).as(r.getContentAsString(java.nio.charset.StandardCharsets.UTF_8)).isEqualTo(expected);return (ObjectNode)mapper.readTree(r.getContentAsByteArray());}
 ObjectNode body(){return mapper.createObjectNode().put("modelId",TestAutomationModelAdapter.ID).put("modelVersion",TestAutomationModelAdapter.VERSION);}
 ObjectNode create(){return service.create(creator,caseId,VersionJson.uuid(),body());}
 ObjectNode queue(ObjectNode n){return service.transition(creator,n.path("id").asText(),VersionJson.uuid(),n.path("recordVersion").asInt(),mapper.createObjectNode().put("action","QUEUE"));}
 ObjectNode cancel(ObjectNode n){return service.transition(creator,n.path("id").asText(),VersionJson.uuid(),n.path("recordVersion").asInt(),mapper.createObjectNode().put("action","CANCEL"));}
 @Test void frozenPublicResponsesStayMinimalAndRealFactsNeverBecomeAnnotations()throws Exception{
  String key=VersionJson.uuid();var response=call("/api/v1/task-documents/"+caseId+"/automation-tasks",token,body(),key,null,200);assertThat(response.path("data").size()).isEqualTo(1);var n=service.create(creator,caseId,key,body());assertThat(n.path("status").asText()).isEqualTo("DRAFT");var doc=data.read("taskDocument",caseId);var task=data.read("task",taskId);
  call("/api/v1/automation-tasks/"+n.path("id").asText()+"/transitions",token,mapper.createObjectNode().put("action","QUEUE"),VersionJson.uuid(),1,200);assertThat(worker.processOne()).isTrue();assertThat(worker.processOne()).isFalse();var detail=service.detail(creator,n.path("id").asText());assertThat(detail.path("task").path("status").asText()).as(detail.toString()).isEqualTo("COMPLETED");assertThat(detail.path("suggestions")).hasSize(1);var c=detail.path("suggestions").get(0);assertThat(c.path("status").asText()).isEqualTo("PENDING_HUMAN_REVIEW");assertThat(c.path("confidence").asDouble()).isZero();assertThat(c.path("targetDraftId").isNull()).isTrue();assertThat(versions.versions(caseId)).isEmpty();assertThat(data.find("draft","taskDocumentId",caseId)).isEmpty();assertThat(data.read("taskDocument",caseId)).isEqualTo(doc);assertThat(data.read("task",taskId)).isEqualTo(task);
  var list=mvc.perform(get("/api/v1/automation-tasks?taskId="+taskId).header("Authorization","Bearer "+token)).andReturn().getResponse();assertThat(list.getStatus()).isEqualTo(200);var item=mapper.readTree(list.getContentAsByteArray()).path("data").path("items").get(0);assertThat(item.size()).isEqualTo(2);assertThat(item.has("id")).isFalse();var read=mvc.perform(get("/api/v1/automation-tasks/"+n.path("id").asText()).header("Authorization","Bearer "+token)).andReturn().getResponse();assertThat(mapper.readTree(read.getContentAsByteArray()).path("data").size()).isEqualTo(3);
 }
 @Test void rolesOwnersPermissionRevocationAndDisabledTasksAreEnforced(){for(String dev:List.of("admin-wang","annotator-chen","arbiter-zhao","expert-qian"))assertThatThrownBy(()->service.create(identity.authenticate("Bearer dev-"+dev),caseId,VersionJson.uuid(),body())).isInstanceOf(BusinessException.class);var task=data.read("task",taskId);task.put("autoPreannotationEnabled",false);data.replace("task",task);assertThatThrownBy(this::create).hasMessageContaining("未启用");task.put("autoPreannotationEnabled",true).put("ownerUserId",VersionJson.uuid());data.replace("task",task);assertThatThrownBy(this::create).hasMessageContaining("OWNER");}
 @Test void idempotencyOptimisticLockAndTerminalStateRulesAreDurable(){String key=VersionJson.uuid();var n=service.create(creator,caseId,key,body());assertThat(service.create(creator,caseId,key,body())).isEqualTo(n);assertThatThrownBy(()->service.create(creator,caseId,key,body().put("modelVersion","changed"))).hasMessageContaining("不同内容");assertThatThrownBy(this::create).hasMessageContaining("未结束");String qkey=VersionJson.uuid();var q=service.transition(creator,n.path("id").asText(),qkey,1,mapper.createObjectNode().put("action","QUEUE"));assertThatThrownBy(()->cancel(n)).hasMessageContaining("刷新");var c=cancel(q);assertThat(c.path("status").asText()).isEqualTo("CANCELLED");assertThat(service.transition(creator,n.path("id").asText(),qkey,1,mapper.createObjectNode().put("action","QUEUE"))).isEqualTo(q);assertThat(worker.processOne()).isFalse();assertThatThrownBy(()->queue(c)).hasMessageContaining("当前状态");assertThat(create().path("id")).isNotEqualTo(n.path("id"));}
 @Test void schemaExtraFieldsUnknownModelsAndLockedBusinessSourcesAreRejected()throws Exception{call("/api/v1/task-documents/"+caseId+"/automation-tasks",token,body().put("status","COMPLETED"),VersionJson.uuid(),null,400);assertThatThrownBy(()->service.create(creator,caseId,VersionJson.uuid(),body().put("modelId","real-but-not-configured"))).hasMessageContaining("尚未接入");var task=data.read("task",taskId).put("status","COMPLETED");data.replace("task",task);assertThatThrownBy(this::create).hasMessageContaining("锁定");assertThat(data.find("automationTask","taskDocumentId",caseId)).isEmpty();}
 @Test void invalidOutputIsRejectedAsAWholeAndRunningCannotBeCancelled(){var n=queue(create());var job=service.claim(n.path("id").asText());assertThat(job.task().path("status").asText()).isEqualTo("RUNNING");assertThatThrownBy(()->cancel(job.task())).hasMessageContaining("当前状态");var output=adapter.generate(job.input());output.add(output.get(0).deepCopy());((ObjectNode)output.get(1)).put("endOffset",Integer.MAX_VALUE);service.finish(job,output,false);var failed=service.read(creator,n.path("id").asText());assertThat(failed.path("status").asText()).isEqualTo("FAILED");assertThat(data.find("modelSuggestion","automationTaskId",n.path("id").asText())).isEmpty();assertThat(create().path("status").asText()).isEqualTo("DRAFT");}
 @Test void changedSourceOrRevokedAuthorizationCannotPublish(){var n=queue(create());var text=data.read("text",n.path("documentTextVersionId").asText());text.put("normalizedText",text.path("normalizedText").asText()+"变更");data.replace("text",text);worker.processOne();assertThat(service.read(creator,n.path("id").asText()).path("status").asText()).isEqualTo("FAILED");assertThat(data.find("modelSuggestion",null,null)).isEmpty();}
 @Test void workerLeaseExpiryAndLateCompletionDoNotDuplicateCandidates(){var n=queue(create());var job=service.claim(n.path("id").asText());var run=data.read("automationRun",n.path("id").asText()).put("expiresAt","2000-01-01T00:00:00Z");data.replace("automationRun",run);service.expire(n.path("id").asText());service.finish(job,adapter.generate(job.input()),false);assertThat(service.read(creator,n.path("id").asText()).path("failureCode").asText()).isEqualTo("EXECUTION_INTERRUPTED");assertThat(data.find("modelSuggestion",null,null)).isEmpty();}
 @Test void failedAuditRollsBackCandidatePublicationAndSameClaimCanRetry(){var n=queue(create());var job=service.claim(n.path("id").asText());doThrow(new BusinessException(ErrorCode.CONFLICT,"audit unavailable")).when(repository).event(org.mockito.ArgumentMatchers.any(),org.mockito.ArgumentMatchers.eq("WORKER_COMPLETE"),org.mockito.ArgumentMatchers.anyString());assertThatThrownBy(()->service.finish(job,adapter.generate(job.input()),false)).isInstanceOf(BusinessException.class);assertThat(service.read(creator,n.path("id").asText()).path("status").asText()).isEqualTo("RUNNING");assertThat(data.find("modelSuggestion",null,null)).isEmpty();reset(repository);service.finish(job,adapter.generate(job.input()),false);service.finish(job,adapter.generate(job.input()),false);assertThat(data.find("modelSuggestion","automationTaskId",n.path("id").asText())).hasSize(1);}
 @Test void concurrentWorkersClaimExactlyOnce()throws Exception{var n=queue(create());var pool=Executors.newFixedThreadPool(2);try{var a=pool.submit(()->worker.processOne());var b=pool.submit(()->worker.processOne());a.get(15,TimeUnit.SECONDS);b.get(15,TimeUnit.SECONDS);}finally{pool.shutdownNow();}assertThat(data.find("modelSuggestion","automationTaskId",n.path("id").asText())).hasSize(1);assertThat(data.find("automationEvent","automationTaskId",n.path("id").asText()).stream().filter(e->"WORKER_CLAIM".equals(e.path("operation").asText())).count()).isEqualTo(1);}
 @Test void adapterExceptionsFailSafelyWithoutInventingModelSuccess(){var n=queue(create());doThrow(new IllegalStateException("secret/path/credential")).when(adapter).generate(org.mockito.ArgumentMatchers.any());worker.processOne();var r=service.read(creator,n.path("id").asText());assertThat(r.path("status").asText()).isEqualTo("FAILED");assertThat(r.toString()).doesNotContain("secret/path");assertThat(data.find("modelSuggestion",null,null)).isEmpty();}
 @Test void twoAssignmentsReadSameImmutableCandidateWithoutSharingHumanReview(){var n=queue(create());worker.processOne();var doc=data.read("taskDocument",caseId);var ids=new ArrayList<String>();for(String dev:List.of("annotator-chen","annotator-liu")){var actor=identity.authenticate("Bearer dev-"+dev);var m=mapper.createObjectNode();VersionJson.stamp(m,creator.id(),VersionJson.now());m.put("taskId",taskId).put("userId",actor.id()).put("memberRole","ANNOTATOR").put("status","ACTIVE");repository.insert("member",m);var a=mapper.createObjectNode();VersionJson.stamp(a,creator.id(),VersionJson.now());a.put("taskDocumentId",caseId).put("taskMemberId",m.path("id").asText()).put("userId",actor.id()).put("assignmentRole","ANNOTATOR").put("status","ACTIVE");repository.insert("assignment",a);ids.add(a.path("id").asText());}var chen=identity.authenticate("Bearer dev-annotator-chen");var liu=identity.authenticate("Bearer dev-annotator-liu");var first=service.suggestionsForAssignment(chen,ids.get(0));assertThat(service.suggestionsForAssignment(liu,ids.get(1))).isEqualTo(first);assertThat(first.path("items")).hasSize(1);assertThatThrownBy(()->service.suggestionsForAssignment(chen,ids.get(1))).isInstanceOf(BusinessException.class);assertThat(service.suggestionsForAssignment(chen,ids.get(0))).isEqualTo(first);assertThat(data.find("draft","taskDocumentId",caseId)).isEmpty();}
 @Test void storedInputTamperingIsRejectedBeforeAdapterSeesIt(){var n=queue(create());var frozen=data.read("automationInput",n.path("id").asText());((ObjectNode)frozen.path("input").path("text")).put("normalizedText","forged input");data.replace("automationInput",frozen);worker.processOne();verify(adapter,never()).generate(org.mockito.ArgumentMatchers.any());assertThat(service.read(creator,n.path("id").asText()).path("status").asText()).isEqualTo("FAILED");}
 @Test void authorizationRevokedWhileRunningRejectsCompletion(){var n=queue(create());var job=service.claim(n.path("id").asText());var role=data.find("role",null,null).stream().filter(r->"TASK_CREATOR".equals(r.path("code").asText())).findFirst().orElseThrow();var permissions=role.putArray("permissionCodes");permissions.add("TASK_CREATE");data.replace("role",role);service.finish(job,adapter.generate(job.input()),false);assertThat(data.read("automationTask",n.path("id").asText()).path("status").asText()).isEqualTo("FAILED");assertThat(data.find("modelSuggestion",null,null)).isEmpty();assertThatThrownBy(()->service.read(creator,n.path("id").asText())).isInstanceOf(BusinessException.class);}

}
